const repl = require('repl');
const { PassThrough } = require('stream');
const input = new PassThrough(), output = new PassThrough(); let out = '';
output.on('data', (d) => (out += d));
const r = repl.start({ input, output, prompt: '> ', terminal: false, useColors: false });
r.context.injected = 41;
r.defineCommand('hi', { help: 'say hi', action(n) { this.output.write('hi ' + n + '\n'); this.displayPrompt(); } });
input.write('injected + 1\n'); input.write('.hi bob\n'); input.write('var z = 3; z * 2\n'); input.write('typeof require + " " + typeof module\n'); input.write('throw new Error("x")\n'); input.write('_error.message\n');
r.on('exit', () => { console.log(JSON.stringify(out)); console.log('exited'); });
setTimeout(() => input.end(), 200);
console.log(typeof repl.REPLServer, typeof repl.builtinModules, repl.REPL_MODE_SLOPPY !== undefined, typeof repl.writer);
